DO $$
DECLARE
  v_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM productbatches pb
  JOIN products p ON pb.prodlink = p.prodcode
  WHERE pb.tempsense = 'High'
    AND CAST(REPLACE(REPLACE(pb.valusd, '$', ''), ',', '') AS numeric) > 100000;

  RAISE NOTICE 'Found % top-tier batches', v_count;

  UPDATE productbatches pb
  SET valusd = '[TOP-TIER] ' || pb.valusd
  WHERE batchtag IN (
    SELECT pb2.batchtag
    FROM productbatches pb2
    JOIN products p2 ON pb2.prodlink = p2.prodcode
    WHERE pb2.tempsense = 'High'
      AND CAST(REPLACE(REPLACE(pb2.valusd, '$', ''), ',', '') AS numeric) > 100000
  );

  RAISE NOTICE 'Updated % records', v_count;
END $$;

DO $$
DECLARE
  rec RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR rec IN
    SELECT pb.batchtag, pb.prodlink, p.prodlabel, pb.valusd
    FROM productbatches pb
    JOIN products p ON pb.prodlink = p.prodcode
    WHERE pb.tempsense = 'High'
      AND CAST(REPLACE(REPLACE(pb.valusd, '$', ''), ',', '') AS numeric) > 100000
  LOOP
    RAISE NOTICE 'Batch: %, Product: %, Label: %, Value: %', rec.batchtag, rec.prodlink, rec.prodlabel, rec.valusd;
    UPDATE productbatches SET valusd = '[TOP-TIER] ' || valusd WHERE batchtag = rec.batchtag;
    v_count := v_count + 1;
  END LOOP;
  RAISE NOTICE 'Total top-tier batches found and updated: %', v_count;
END $$;
